 fishGame={fish:FISH[53],kingTrial:true,lesson:false,tutorial:true,bait:'none',loadout:{},training:false,progress:.16,y:.84,target:.84,bar:.64,size:.36,velocity:0,fishVelocity:0,fixedRemainder:0,time:0,out:0,treasure:false,treasureY:0,treasureProgress:0,treasureWon:false,lastInside:true,trialStage:-1,trialHold:0,trialReleased:false};
