function finishDebris(roll,source){EQ.gain(state,source==='trap'?5:3);if(source!=='trap')advanceTime();var item=DEBRIS[roll.junk];state.debris.push(roll.junk);pendingCatch={debris:true};setPhase('result');modal('<h2 id="modal-title">'+item.name+'</h2><p>这次水里带上来的是一件杂物。<br>已经放入鱼篓，可以出售或丢弃，不计入鱼类图鉴。</p><div class="modal-actions"><button class="primary" data-action="keep-catch">收好，继续钓鱼</button></div>');render();save();}
