function musicPanel(){var count=window.ReedMusicCatalog?window.ReedMusicCatalog.tracks.length:100;return '<div class="music-panel"><small>正在聆听 · ConcernedApe</small><strong id="music-now"></strong><p id="music-status" role="status"></p><div class="music-modes">'+[['auto','随环境'],['shuffle','随机播放'],['single','单曲循环']].map(function(m){return '<button data-action="music-mode-'+m[0]+'" data-music-mode="'+m[0]+'">'+m[1]+'</button>';}).join('')+'</div><div class="music-transport"><button data-action="music-previous" aria-label="上一首音乐">‹ 上一首</button><button data-action="music-library">曲库 · '+count+'首</button><button data-action="music-next" aria-label="下一首音乐">下一首 ›</button></div></div>';}
function syncMusicHUD(info){if(!state||!state.settings)return;info=info||(window.ReedAudio.getStatus?window.ReedAudio.getStatus():{});var title=document.getElementById('music-now'),status=document.getElementById('music-status');if(title)title.textContent=info.musicTitle||(window.ReedMusic&&window.ReedMusic.title)||'背景音乐';if(status)status.textContent=!prefs().bgm?'背景音乐已关闭':prefs().musicVolume===0?'音乐音量为0':info.musicError?'暂时未能播放，点下一首重试':info.musicLoading?'正在加载这一首…':(info.musicMode==='auto'?(info.musicScene||'随环境选曲')+' · ':info.musicMode==='shuffle'?'完整曲库随机播放 · ':'单曲循环 · ')+(info.musicPlaying?'播放中':'触摸后播放');Array.prototype.forEach.call(document.querySelectorAll('[data-music-mode]'),function(b){var on=b.dataset.musicMode===(prefs().musicMode||'auto');b.classList.toggle('chosen',on);b.setAttribute('aria-pressed',String(on));});Array.prototype.forEach.call(document.querySelectorAll('[data-music-id]'),function(b){var on=b.dataset.musicId===info.musicId;b.classList.toggle('playing',on);b.setAttribute('aria-pressed',String(on));});}
var musicSearch='',musicFilter='all',musicPage=0;
function musicGrid(){var C=window.ReedMusicCatalog;if(!C)return '';var query=musicSearch.toLowerCase(),list=C.tracks.filter(function(t){var group=C.group(t);return (musicFilter==='all'||(musicFilter==='四季'?['春季','夏季','秋季','冬季'].indexOf(group)>=0:group===musicFilter))&&(!query||(t.title+' '+group+' '+t.number).toLowerCase().indexOf(query)>=0);});var pages=Math.max(1,Math.ceil(list.length/20));musicPage=clamp(musicPage,0,pages-1);return '<p class="music-count">'+list.length+' / '+C.tracks.length+' 首 · 第 '+(musicPage+1)+' / '+pages+' 页</p>'+list.slice(musicPage*20,musicPage*20+20).map(function(t){var seconds=Math.round(t.duration);return '<button class="music-track" data-action="music-play-'+t.id+'" data-music-id="'+t.id+'"><span class="track-number">'+('00'+t.number).slice(-3)+'</span><span class="track-name">'+esc(t.title)+'<small>'+C.group(t)+' · 节选 '+Math.floor(seconds/60)+':'+('0'+seconds%60).slice(-2)+'</small></span><span class="track-play" aria-hidden="true">♪</span></button>';}).join('')+(list.length?'':'<p class="empty">没有找到这首曲子，试试英文曲名或季节。</p>')+(pages>1?'<div class="music-pagination"><button class="secondary" data-action="music-page-previous" '+(!musicPage?'disabled':'')+'>上一页</button><span>'+(musicPage+1)+' / '+pages+'</span><button class="secondary" data-action="music-page-next" '+(musicPage===pages-1?'disabled':'')+'>下一页</button></div>':'');}
function musicLibrary(){if(!idleOnly())return;musicSearch='';musicFilter='all';musicPage=0;modal('<h2 id="modal-title">水边留声机</h2><p class="music-intro">16首精选原声节选，每首最长60秒，循环陪你钓鱼。</p>'+musicPanel()+'<label class="music-search"><span class="sr-only">搜索音乐曲名或季节</span><input id="music-search" type="search" placeholder="搜索曲名或季节" aria-label="搜索音乐曲名或季节"></label><div class="music-filters">'+['all','四季','场景'].map(function(k){return '<button data-action="music-filter-'+k+'" data-music-filter="'+k+'" class="'+(k==='all'?'chosen':'')+'">'+(k==='all'?'全部':k==='活动与其他'?'其他':k)+'</button>';}).join('')+'</div><div id="music-results" class="music-results">'+musicGrid()+'</div><button class="wide-link" data-action="music-settings">返回声音设置</button>');$('modal').setAttribute('data-sheet','music');syncMusicHUD();}
function musicAction(a){if(a.indexOf('music-')!==0)return false;if(!idleOnly())return true;var p=prefs();if(a==='music-page-previous'||a==='music-page-next'){musicPage+=a==='music-page-next'?1:-1;$('music-results').innerHTML=musicGrid();$('music-results').scrollTop=0;syncMusicHUD();return true;}if(a==='music-library'){musicLibrary();return true;}if(a==='music-settings'){settingsModal();return true;}if(a.indexOf('music-filter-')===0){musicFilter=a.slice(13);musicPage=0;$('music-results').innerHTML=musicGrid();Array.prototype.forEach.call(document.querySelectorAll('[data-music-filter]'),function(b){b.classList.toggle('chosen',b.dataset.musicFilter===musicFilter);});syncMusicHUD();return true;}if(a.indexOf('music-mode-')===0){var mode=a.slice(11);if(['auto','single','shuffle'].indexOf(mode)<0)return true;p.musicMode=mode;if(mode==='single'&&window.ReedAudio.getStatus){var playing=window.ReedAudio.getStatus().musicId;if(playing)p.musicTrack=playing;}configureAudio();syncMusicScene();syncMusicHUD();save();return true;}if(a.indexOf('music-play-')===0){var id=a.slice(11);if(!window.ReedMusicCatalog||!window.ReedMusicCatalog.byId[id])return true;p.musicMode='single';p.musicTrack=id;p.bgm=true;unlockAudio();configureAudio();syncMusicHUD();save();return true;}if(a==='music-next'||a==='music-previous'){p.bgm=true;unlockAudio();configureAudio();var fn=a==='music-next'?'next':'previous';if(window.ReedAudio[fn])window.ReedAudio[fn]();if(window.ReedAudio.getStatus)p.musicTrack=window.ReedAudio.getStatus().musicId||p.musicTrack;syncMusicHUD();save();return true;}return true;}
$('modal-body').addEventListener('input',function(e){if(e.target.id==='music-search'){musicSearch=e.target.value.trim();musicPage=0;$('music-results').innerHTML=musicGrid();syncMusicHUD();}});

function settingsModal(){if(!idleOnly())return;var p=prefs();modal('<h2 id="modal-title">设置</h2><p class="settings-intro">把水边，调成你喜欢的样子。</p>'+settingSwitch('bgm','背景音乐','16首精选原声节选 · ConcernedApe',p.bgm)+musicPanel()+settingRange('musicVolume','音乐音量',p.musicVolume)+settingSwitch('sound','游戏音效','抛竿、落水、咬钩与提竿提示',state.sound)+settingRange('sfxVolume','音效音量',p.sfxVolume)+settingSwitch('effects','装饰动效','水波、天气与镜头缓动；保留必要操作反馈',p.effects)+settingSwitch('vibration','触感反馈','蓄力与咬钩提示，支持震动的设备上生效',p.vibration)+kingMemoryCard()+'<button class="wide-link" data-action="learn-touch">重新练习触屏钓鱼</button><button class="wide-link" data-action="welcome-title">返回欢迎页</button><div class="settings-storage"><strong>本机存档</strong><p id="settings-save-state">'+(storageReadFailed?'读取失败，当前进度临时保留':lastSaved?'已读取本机存档 · 游戏进度自动保存':'自动保存已开启')+'</p><small>金币、鱼获、图鉴、装备和设置都会保存。<br>使用同一设备与入口继续；清理数据后需用备份恢复。</small><div class="modal-actions"><button class="secondary" data-action="save-now">立即保存</button><button class="primary" data-action="backup">备份与恢复</button></div></div>');syncMusicHUD();}
function settingSwitch(key,name,desc,on){return '<label class="setting-row"><span><b>'+name+'</b><small>'+desc+'</small></span><input type="checkbox" role="switch" data-setting="'+key+'" '+(on?'checked':'')+' aria-label="'+name+'"></label>';}
function settingRange(key,name,n){return '<label class="setting-volume"><span>'+name+' <output id="value-'+key+'">'+Math.round(n*100)+'%</output></span><input type="range" min="0" max="100" step="5" value="'+Math.round(n*100)+'" data-setting="'+key+'" aria-label="'+name+'"></label>';}
function changeSetting(e){var key=e.target.dataset.setting;if(!key)return;unlockAudio();if(key==='sound'){state.sound=e.target.checked;state.soundPreference=state.sound?'on':'off';}else if(key==='musicVolume'||key==='sfxVolume'){prefs()[key]=clamp(Number(e.target.value)/100,0,1);$('value-'+key).textContent=Math.round(prefs()[key]*100)+'%';}else prefs()[key]=e.target.checked;configureAudio();render();laterSave();}
$('modal-body').addEventListener('input',changeSetting);$('modal-body').addEventListener('change',function(e){if(e.target.type==='checkbox')changeSetting(e);});

function welcomeSummary(){var d=RULES.date(state),hour=Math.floor(state.minutes/60)%24,minute=state.minutes%60;return '<strong>第'+d.year+'年 · '+RULES.seasons[d.season]+d.day+'日 · '+('0'+hour).slice(-2)+':'+('0'+minute).slice(-2)+'</strong><span>'+esc(state.home?'河畔小屋':POOLS[state.pool].name)+' · 钓鱼'+EQ.base(state)+'级</span><div class="welcome-stats"><span>'+state.coins.toLocaleString()+' 金币</span><span>发现 '+Object.keys(state.book).length+' / 77 种</span></div>';}
function drawWelcome(){var cv=$('welcome-landscape'),w=Math.min(480,window.innerWidth||390),h=window.innerHeight||844;cv.width=Math.ceil(w/2);cv.height=Math.ceil(h/2);var c=cv.getContext('2d');c.imageSmoothingEnabled=false;if(window.ReedArt){window.ReedArt.drawTitle(c,cv.width,cv.height,0);return;}c.fillStyle='#86a6eb';c.fillRect(0,0,cv.width,cv.height);}
function showWelcomeLoading(){startupOpen=true;$('welcome').hidden=false;$('app').setAttribute('inert','');$('app').setAttribute('aria-hidden','true');$('welcome-actions').innerHTML='<p class="welcome-loading" role="status">正在读取本机存档…</p>';$('welcome-note').textContent='金币、鱼获和图鉴会自动保存在这台设备。';drawWelcome();}
function showWelcome(){startupOpen=true;clearTimeout(saveTimer);$('welcome').hidden=false;$('app').setAttribute('inert','');$('app').setAttribute('aria-hidden','true');window.ReedAudio.setActive(true);var html='';if(storageReadFailed){html='<div class="welcome-save warning"><strong>暂时无法读取本机存档</strong><span>原存档不会被覆盖。你可以重新读取，或用备份码恢复。</span></div><button class="primary" data-action="welcome-retry">重新读取</button><button class="secondary" data-action="welcome-load">读取备份存档</button><button class="wide-link" data-action="welcome-temporary">先临时试玩</button>';}else{if(hasLocalSave)html='<div class="welcome-save" aria-label="本机存档"><small>上次的垂钓时光</small>'+welcomeSummary()+'</div><button id="welcome-continue" class="primary" data-action="welcome-continue">继续游戏</button><div class="welcome-secondary"><button class="secondary" data-action="welcome-new">开始新游戏</button><button class="secondary" data-action="welcome-load">读取存档</button></div>';else html='<div class="welcome-save welcome-fresh"><strong>第一竿，从春天开始</strong><span>水面向水面滑动，滑远投远，松手抛竿。<br>第一次垂钓会有一步步的引导。</span></div><button class="primary" data-action="welcome-new">开始新游戏</button><button class="secondary" data-action="welcome-load">读取存档</button>';}$('welcome-actions').innerHTML=html;$('welcome-note').textContent=storageReadFailed?'临时试玩不会写入原存档，离开前请在设置中备份。':'进度自动保存在本机 · 换设备时可用备份码读取';drawWelcome();if(window.ReedArt)window.ReedArt.prepare(state);var first=$('welcome-actions').querySelector('button');if(first)first.focus();}
function enterFromWelcome(){startupOpen=false;$('welcome').hidden=true;$('app').removeAttribute('inert');$('app').removeAttribute('aria-hidden');closeModal();lastFrame=0;setMobileView('home');render();refreshLayout();drawScene(sceneTime);configureAudio();window.ReedAudio.setActive(true);save();$('world').focus();}
function welcomeLoadModal(){window.pendingImport=null;modal('<h2 id="modal-title">读取存档</h2>'+(hasLocalSave&&!storageReadFailed?'<div class="welcome-save">'+welcomeSummary()+'</div><button class="primary" data-action="welcome-continue">读取本机存档</button>':'<p>这台设备'+(storageReadFailed?'的存档暂时无法读取':'还没有存档')+'，可以粘贴以前保存的备份码。</p>')+'<label class="restore-label" for="save-code">从备份码恢复</label><textarea id="save-code" aria-label="存档备份码" placeholder="在这里粘贴完整备份码" spellcheck="false"></textarea><p class="panel-note">先校验并确认，再替换当前进度。备份码错误不会改变存档。</p><button class="primary" data-action="import-save">检查并读取备份</button><p id="import-status" role="status"></p>');$('save-code').value='';}
function welcomeAction(a){if(a==='welcome-title'){if(!idleOnly())return true;closeModal();clearFishing();save();showWelcome();return true;}if(a==='welcome-retry'){if(!startupOpen)return true;showWelcomeLoading();load().then(showWelcome);return true;}if(a==='welcome-load'){if(startupOpen)welcomeLoadModal();return true;}if(a==='welcome-continue'){if(startupOpen&&hasLocalSave&&!storageReadFailed)enterFromWelcome();return true;}if(a==='welcome-temporary'){if(startupOpen&&storageReadFailed)enterFromWelcome();return true;}if(a==='welcome-new'){if(!startupOpen||storageReadFailed)return true;if(hasLocalSave){confirmAction('开始新的垂钓日记？','新游戏会替换本机进度（'+dateLabel()+'，'+state.coins+'金币）。需要保留时，请先继续游戏，在设置中复制存档备份码。','welcome-confirm-new');}else welcomeAction('welcome-confirm-new');return true;}if(a==='welcome-confirm-new'){if(!startupOpen||storageReadFailed)return true;clearFishing();state=defaults();hasLocalSave=false;bookSearch='';bookFilter='all';lessonStep=0;dayEnding=false;window.pendingImport=null;enterFromWelcome();return true;}return false;}
