function saveModal(){if(!idleOnly())return;modal('<h2 id="modal-title">好好保存这段时光</h2><p>进度会自动保存在当前设备。重要存档请定期备份，卸载或清理数据可能使本地进度丢失。</p><p>备份码已显示在下方，可长按选择并复制；恢复时将完整备份码粘贴到这里。</p><textarea id="save-code" aria-label="存档备份码"></textarea><div class="modal-actions"><button class="secondary" data-action="select-save">选中备份码</button><button class="primary" data-action="import-save">恢复存档</button></div><p id="import-status" role="status"></p>');$('save-code').value=JSON.stringify(state);}
function action(a){if(welcomeAction(a))return;if(musicAction(a))return;var aliases={'buy-lead':'stock-tackle-lead','buy-barbed':'stock-tackle-barbed','buy-spinner':'stock-tackle-spinner','buy-dressed':'stock-tackle-dressed','buy-trap-bobber':'stock-tackle-trap','buy-bait':'stock-bait-bait','buy-lucky':'stock-bait-lucky'};a=aliases[a]||a;if(newAction(a))return;if(a==='backup'){saveModal();return;}if(a==='save-now'){save();saveChain.then(function(){$('settings-save-state').textContent=$('save-status').textContent;});return;}if(a==='wake'){closeModal();render();return;}if(a==='sleep-now'){finishDay(false);return;}if(a==='confirm-season-rest'){clearFishing();DAY.untilSeason(state);render();save();modal('<h2 id="modal-title">新季节的清晨</h2><p>'+dateLabel()+' · 清晨06:00<br>体力已恢复，鱼讯和天气都更新了。</p><button class="primary" data-action="wake">起床</button>');return;}if(a==='eat-food'){if(state.food>0&&state.energy<state.maxEnergy){state.food--;state.energy=Math.min(state.maxEnergy,state.energy+45);render();save();toast('吃了饭团，体力恢复45点。');}energyModal();return;}if(a==='buy-food'){if(state.coins>=20&&state.food<999){state.coins-=20;state.food++;render();save();}energyModal();return;}if(a==='go-fishing'){if(!idleOnly())return;closeModal();setMobileView('home');render();return;}if(a==='close'){closeModal(true);return;}if(a==='keep-catch'){keepCatch();return;}if(a==='sell-catch'&&pendingCatch){var i=state.bag.indexOf(pendingCatch);if(i>=0){state.coins+=EQ.sellValue(state,pendingCatch);state.bag.splice(i,1);}keepCatch();toast('鱼获已出售，金币已入账。');return;}if(a==='select-save'){$('save-code').focus();$('save-code').select();return;}if(a==='import-save'){try{var imported=JSON.parse($('save-code').value);imported=upgradeSave(imported);if(!validSave(imported))throw new Error('bad');window.pendingImport=Object.assign(defaults(),imported);confirmAction('恢复这份存档？','将替换当前进度：第 '+imported.day+' 天，'+imported.coins+' 金币，累计 '+imported.total+' 条鱼。','confirm-import');}catch(e){$('import-status').textContent='备份码无效，当前进度没有改变。';}return;}if(a==='confirm-import'){if(window.pendingImport){clearFishing();state=window.pendingImport;window.pendingImport=null;storageReadFailed=false;hasLocalSave=true;if(state.energy===0)DAY.next(state,true);if(!EQ.canBait(state))state.selectedBait='none';configureAudio();closeModal();if(startupOpen)enterFromWelcome();else{setMobileView('home');render();save();}toast('存档已恢复。');}return;}if(specialAction(a))return;if(!idleOnly())return;
if(a==='sell-all'){if(!bagSize())return;confirmAction('出售普通鱼获？','初代鱼王会留在鱼篓中。其他鱼获（含旧版纪念鱼获）会出售，图鉴记录保留。','confirm-sell-all');return;}
if(a==='confirm-sell-all'){var selling=state.bag.filter(function(f){return FISH[f.id].category!=='legend';}),sum=selling.concat(state.legacyBag).reduce(function(v,f){return v+EQ.sellValue(state,f);},0);state.coins+=sum;state.bag=state.bag.filter(function(f){return FISH[f.id].category==='legend';});state.legacyBag=[];closeModal();toast('普通鱼获已出售，获得 '+sum+' 金币。');}
render();save();}
$('tab-content').addEventListener('click',function(e){var el=e.target.closest('[data-action],[data-pool],[data-unlock],[data-sell],[data-legacy-sell],[data-rod],[data-book],[data-filter],[data-debris]');if(!el||el.disabled)return;if(el.hasAttribute('data-debris')){if(!idleOnly())return;var ix=+el.dataset.debris;if(state.debris[ix]===undefined)return;state.coins+=DEBRIS[state.debris[ix]].value;state.debris.splice(ix,1);render();save();return;}if(el.hasAttribute('data-filter')){bookFilter=el.dataset.filter;renderTab();return;}if(el.hasAttribute('data-legacy-sell')){if(!idleOnly())return;var oldIndex=+el.dataset.legacySell;if(state.legacyBag[oldIndex]){state.coins+=state.legacyBag[oldIndex].value;state.legacyBag.splice(oldIndex,1);render();save();}return;}if(el.hasAttribute('data-book')){showBook(+el.dataset.book);return;}if(!idleOnly())return;if(el.hasAttribute('data-action')){action(el.dataset.action);return;}if(el.hasAttribute('data-pool')){if(!travelTo(+el.dataset.pool))return;state.pool=+el.dataset.pool;state.spot=0;state.aim=null;state.facing=facingForAim();state.home=false;castLanding=null;render();$('scene-tip').textContent='等风来，也等一条鱼。';setMobileView('home');save();sound(440);return;}if(el.hasAttribute('data-unlock')){var p=POOLS[+el.dataset.unlock];if(level()>=p.level&&state.coins>=p.cost&&state.unlocked.indexOf(p.id)<0){state.coins-=p.cost;state.unlocked.push(p.id);if(!travelTo(p.id)){render();save();return;}state.pool=p.id;state.spot=0;state.aim=null;state.facing=facingForAim();state.home=false;castLanding=null;render();$('scene-tip').textContent='等风来，也等一条鱼。';setMobileView('home');save();toast(p.name+' 已解锁！');}return;}if(el.hasAttribute('data-sell')){var i=+el.dataset.sell;if(state.bag[i]){state.coins+=EQ.sellValue(state,state.bag[i]);state.bag.splice(i,1);render();save();sound(740);}return;}if(el.hasAttribute('data-rod')){buyRod(+el.dataset.rod);}});
