$('modal-body').addEventListener('click',function(e){var b=e.target.closest('[data-action],[data-bait],[data-season],[data-calendar-fish],[data-tackle],[data-water-power],[data-spot],[data-equip],[data-slot],[data-target]');if(!b||b.disabled)return;if(modalActionOnly&&(performance.now()-modalOpenedAt<350||(e.detail>0&&modalArmedButton!==b))){e.preventDefault();return;}modalArmedButton=null;if(b.hasAttribute('data-slot')){selectedSlot=+b.dataset.slot;baitModal();return;}if(b.hasAttribute('data-equip')){if(idleOnly()){EQ.equip(state,b.dataset.equip==='none'?null:+b.dataset.equip,selectedSlot);render();save();baitModal();}return;}if(b.hasAttribute('data-target')){state.targetedFish=+b.dataset.target;save();baitModal();return;}if(b.hasAttribute('data-spot')){state.spot=+b.dataset.spot;state.aim=null;state.facing=facingForAim();castLanding=null;closeModal();render();save();return;}if(b.hasAttribute('data-water-power')){waterInfoModal(+b.dataset.waterPower);return;}if(b.hasAttribute('data-tackle')){if(!idleOnly())return;state.tackle=b.dataset.tackle;render();save();baitModal();return;}if(b.hasAttribute('data-calendar-fish')){showBook(+b.dataset.calendarFish);return;}if(b.hasAttribute('data-season')){if(idleOnly())seasonGo(+b.dataset.season);return;}if(b.hasAttribute('data-bait')){if(!idleOnly())return;if(b.dataset.bait!=='none'&&(!EQ.canBait(state)||!EQ.stock(state,b.dataset.bait)))return;state.selectedBait=b.dataset.bait;render();save();baitModal();return;}action(b.dataset.action);});
