function help(){modal('<h2 id="modal-title">慢一点，好鱼会来的。</h2><p>在《星露谷钓鱼》中，收集 77 个图鉴条目，探索四季和19处水域，经营自己的钓鱼日常。</p><ul><li><b>抛竿：</b>在场景水面向想钓的方向滑动，滑得越远投得越远，松手抛出；也可以按住蓄力。力度条到满力即可投到当前等级能到达的最远水面。抛出格数表示距离，水深格数会影响鱼种与品质。</li><li><b>咬钩：</b>浮漂下沉、出现提示后，轻点场景提竿。等待时也可以点击提前收竿，此时没有鱼获，已消耗的体力不退回。</li><li><b>遛鱼：</b>按住让绿色条上浮，松开让它下沉。提前松手能抵消惯性。让鱼留在绿条内，直到右侧进度充满。</li><li><b>宝箱：</b>让绿条覆盖金色宝箱来收集。必须成功钓上鱼才可领取。</li><li><b>作息：</b>每天早上6点开始，菜单和遛鱼时暂停计时。点体力条旁的小屋回家，在床上睡到明天，或连续休息到下一季。凌晨2点或体力耗尽会晕倒、扣钱并丢失全部随身鱼获；图鉴和装备保留。饭团可以补充体力。</li><li><b>钓位：</b>向水面滑动调整方向与力度；部分鱼王需要指定钓位、季节、天气和离岸格数。</li><li><b>成长：</b>卖鱼换装备、补鱼饵与浮标，升级选职业；工坊可熏鱼、附魔和升级小屋。</li><li><b>完美：</b>鱼一次也不离开绿条即为完美；银星升金星、金星升铱星，并获得经验加成。同种同品质的鱼会堆叠，背包可升级到36格。</li></ul><p>抛竿直接在场景中操作；遛鱼时按住绿色控条区域或下方操作区上浮，松开下沉。切到后台会暂停，回来后点“继续钓鱼”。</p><div class="modal-actions"><button class="primary" data-action="go-fishing">去钓一会儿</button></div>');}
$('help-btn').addEventListener('click',help);
// Pointer capture is preferred; Touch Events + mouse are the Chrome 61 / older WebView fallback.
function bindHold(el,onDown,onUp,onCancel){
 function begin(e,id){if(activePointer!==null||paused)return false;activePointer=id;e.preventDefault();onDown();return true;}
 function end(e,id,cancelled){if(activePointer!==id)return;activePointer=null;if(e&&e.cancelable)e.preventDefault();if(cancelled)onCancel();else onUp();}
 if(window.PointerEvent){el.addEventListener('pointerdown',function(e){if(e.isPrimary===false || (e.pointerType==='mouse'&&e.button!==0))return;if(begin(e,e.pointerId)){try{el.setPointerCapture(e.pointerId);}catch(err){}}});el.addEventListener('pointerup',function(e){end(e,e.pointerId,false);});el.addEventListener('pointercancel',function(e){end(e,e.pointerId,true);});el.addEventListener('lostpointercapture',function(e){end(e,e.pointerId,true);});}
 else{el.addEventListener('touchstart',function(e){if(e.changedTouches.length)begin(e,'t'+e.changedTouches[0].identifier);},{passive:false});function touches(e,cancelled){for(var i=0;i<e.changedTouches.length;i++)end(e,'t'+e.changedTouches[i].identifier,cancelled);}el.addEventListener('touchend',function(e){touches(e,false);},{passive:false});el.addEventListener('touchcancel',function(e){touches(e,true);},{passive:false});el.addEventListener('touchmove',function(e){if(activePointer!==null)e.preventDefault();},{passive:false});el.addEventListener('mousedown',function(e){if(e.button===0)begin(e,'mouse');});window.addEventListener('mouseup',function(e){end(e,'mouse',false);});}
 el.addEventListener('contextmenu',function(e){e.preventDefault();});el.addEventListener('dragstart',function(e){e.preventDefault();});
}

function reelDown(){if(phase==='fishing'){hold=true;$('reel-btn').classList.add('pressed');}}
function reelUp(){if(fishGame&&fishGame.kingTrial&&fishGame.trialHold>=.25)fishGame.trialReleased=true;if(fishGame&&fishGame.lesson&&lessonStep===4){lessonStep=5;updateInteraction();}hold=false;$('reel-btn').classList.remove('pressed');}
bindHold($('reel-btn'),reelDown,reelUp,reelUp);bindHold(document.querySelector('.minigame'),reelDown,reelUp,reelUp);
$('give-up').addEventListener('click',function(){finishGame(false);});$('pause-btn').addEventListener('click',pauseSession);$('resume-btn').addEventListener('click',resumeSession);
